//! Sections, headers, footers and page fields: reading the corpus files
//! (tests/corpus/docx, generated by scripts/corpus/gen_docx.py), editing
//! them in Kantor and saving.

use std::collections::BTreeMap;
use std::io::{Cursor, Read as _};
use std::path::PathBuf;

use docs_engine::{
    Align, Document, HfKind, HfType, Orientation, PageField, Position, SectionStart, Selection,
    page_field,
};

fn corpus(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/docx")
        .join(name)
}

fn parts(bytes: &[u8]) -> BTreeMap<String, Vec<u8>> {
    let mut zip = zip::ZipArchive::new(Cursor::new(bytes)).unwrap();
    let mut out = BTreeMap::new();
    for i in 0..zip.len() {
        let mut f = zip.by_index(i).unwrap();
        let name = f.name().unwrap().into_owned();
        let mut v = Vec::new();
        f.read_to_end(&mut v).unwrap();
        out.insert(name, v);
    }
    out
}

fn text(p: &BTreeMap<String, Vec<u8>>, name: &str) -> String {
    String::from_utf8(p[name].clone()).unwrap()
}

#[test]
fn report_sections_headers_and_page_fields() {
    let doc = Document::open(&corpus("report.docx")).unwrap();
    assert!(
        !doc.has_unsupported_content(),
        "{:?}",
        doc.unsupported_content()
    );
    let sections = doc.sections();
    assert_eq!(sections.len(), 3, "portrait, landscape, portrait");
    assert_eq!(sections[0].props.page.orientation(), Orientation::Portrait);
    assert_eq!(sections[1].props.page.orientation(), Orientation::Landscape);
    assert_eq!(sections[2].props.page.orientation(), Orientation::Portrait);
    assert_eq!(sections[1].props.start, SectionStart::NextPage);
    assert!(sections[0].props.title_page);
    // python-docx puts the references on the first section; later ones
    // link to it.
    let header = doc
        .story_index_for(&sections, 2, HfKind::Header, HfType::Default)
        .expect("header linked from section 1");
    assert!(
        doc.stories()[header].doc.paragraphs()[0]
            .text
            .contains("Quarterly Operations Report")
    );
    let first = doc
        .story_index_for(&sections, 0, HfKind::Header, HfType::First)
        .unwrap();
    assert_eq!(
        doc.stories()[first].doc.paragraphs()[0].text,
        "CONFIDENTIAL"
    );
    let footer = doc
        .story_index_for(&sections, 0, HfKind::Footer, HfType::Default)
        .unwrap();
    let fp = &doc.stories()[footer].doc.paragraphs()[0];
    let fields: Vec<PageField> = fp.objects().filter_map(|(_, o)| page_field(o)).collect();
    assert_eq!(fields, [PageField::Page, PageField::NumPages]);
    assert_eq!(
        doc.hf_text(0, HfKind::Footer, HfType::Default).0,
        "Page {PAGE} of {PAGES}"
    );
    let numbered =
        docs_engine::with_page_numbers(doc.stories()[footer].doc.paragraphs(), "3", "7").unwrap();
    assert_eq!(numbered[0].text, "Page 3 of 7");
    assert!(
        !doc.preserved_content().iter().any(|p| p.contains("header")),
        "headers are shown now: {:?}",
        doc.preserved_content()
    );
}

#[test]
fn untouched_headers_save_byte_for_byte() {
    let path = corpus("report.docx");
    let orig = parts(&std::fs::read(&path).unwrap());
    let mut doc = Document::open(&path).unwrap();
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("out.docx");
    // A body edit only.
    doc.insert_text(Selection::caret(Position::new(1, 0)), "Edited. ", None);
    doc.save_as(&out).unwrap();
    let saved = parts(&std::fs::read(&out).unwrap());
    for (name, bytes) in &orig {
        if name.contains("header") || name.contains("footer") || name.ends_with("settings.xml") {
            assert_eq!(&saved[name], bytes, "{name} unchanged");
        }
    }
    // The paragraph-level section breaks are kept.
    let body = text(&saved, "word/document.xml");
    assert_eq!(body.matches("<w:sectPr").count(), 3);
    assert!(body.contains("w:orient=\"landscape\""));
}

#[test]
fn edit_footer_and_add_header_round_trip() {
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("new.docx");
    let mut doc = Document::new();
    doc.insert_text(Selection::default(), "Body text", None);
    let sel = Selection::default();
    assert!(doc.set_hf_text(
        0,
        HfKind::Footer,
        HfType::Default,
        "Page {PAGE} of {PAGES}",
        Some(Align::Center),
        sel
    ));
    assert!(doc.set_hf_text(0, HfKind::Header, HfType::Default, "Acme Report", None, sel));
    doc.set_title_page(0, true, sel);
    assert!(doc.set_hf_text(0, HfKind::Header, HfType::First, "Cover", None, sel));
    doc.set_even_odd_headers(true, sel);
    doc.save_as(&out).unwrap();

    let p = parts(&std::fs::read(&out).unwrap());
    let body = text(&p, "word/document.xml");
    assert!(
        body.contains("w:footerReference w:type=\"default\""),
        "{body}"
    );
    assert!(body.contains("w:headerReference w:type=\"first\""));
    assert!(body.contains("<w:titlePg/>"));
    let ct = text(&p, "[Content_Types].xml");
    assert!(ct.contains("wordprocessingml.footer+xml"));
    assert!(ct.contains("wordprocessingml.header+xml"));
    let rels = text(&p, "word/_rels/document.xml.rels");
    assert!(rels.contains("relationships/footer\""));
    let settings = text(&p, "word/settings.xml");
    assert!(settings.contains("<w:evenAndOddHeaders/>"));
    let footer = p
        .iter()
        .find(|(k, _)| k.starts_with("word/footer"))
        .map(|(_, v)| String::from_utf8(v.clone()).unwrap())
        .unwrap();
    assert!(footer.contains("w:instr=\" PAGE"), "{footer}");
    assert!(footer.contains("NUMPAGES"));
    assert!(footer.contains("<w:jc w:val=\"center\"/>"));

    let again = Document::open(&out).unwrap();
    assert!(again.even_odd_headers());
    assert_eq!(
        again.hf_text(0, HfKind::Footer, HfType::Default).0,
        "Page {PAGE} of {PAGES}"
    );
    assert_eq!(again.hf_text(0, HfKind::Header, HfType::First).0, "Cover");
    assert!(again.sections()[0].props.title_page);
}

#[test]
fn header_edits_undo_and_redo() {
    let mut doc = Document::open(&corpus("letter.docx")).unwrap();
    let sel = Selection::default();
    let before = doc.hf_text(0, HfKind::Header, HfType::Default).0;
    assert!(before.contains("Jl. Sudirman"));
    assert!(doc.even_odd_headers());
    assert_eq!(
        doc.hf_text(0, HfKind::Footer, HfType::Even).0,
        "even footer"
    );
    assert!(doc.set_hf_text(
        0,
        HfKind::Header,
        HfType::Default,
        "New letterhead",
        None,
        sel
    ));
    assert!(doc.is_dirty());
    doc.undo();
    assert_eq!(doc.hf_text(0, HfKind::Header, HfType::Default).0, before);
    doc.redo();
    assert_eq!(
        doc.hf_text(0, HfKind::Header, HfType::Default).0,
        "New letterhead"
    );
    // Saving writes only that header part.
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("letter.docx");
    let orig = parts(&std::fs::read(corpus("letter.docx")).unwrap());
    doc.save_as(&out).unwrap();
    let saved = parts(&std::fs::read(&out).unwrap());
    let changed: Vec<&String> = orig
        .keys()
        .filter(|k| saved.get(*k) != orig.get(*k))
        .collect();
    assert_eq!(changed.len(), 2, "document.xml and one header: {changed:?}");
    assert!(changed.iter().any(|k| k.contains("header")));
}

#[test]
fn section_break_and_section_page_setup() {
    let mut doc = Document::new();
    let c = doc.insert_text(Selection::default(), "first part second part", None);
    assert_eq!(doc.sections().len(), 1);
    let at = Selection::caret(Position::new(0, "first part ".len()));
    let after = doc.insert_section_break(at).unwrap();
    assert_eq!(after.head, Position::new(1, 0));
    let s = doc.sections();
    assert_eq!(s.len(), 2);
    assert_eq!(doc.paragraph(0).text, "first part ");
    assert_eq!(doc.paragraph(1).text, "second part");
    // Landscape for the first section only.
    let p = doc.section_page(0).with_orientation(Orientation::Landscape);
    doc.set_section_page(0, p, c);
    assert_eq!(
        doc.sections()[0].props.page.orientation(),
        Orientation::Landscape
    );
    assert_eq!(
        doc.sections()[1].props.page.orientation(),
        Orientation::Portrait
    );
    doc.undo();
    assert_eq!(
        doc.sections()[0].props.page.orientation(),
        Orientation::Portrait
    );
    doc.redo();
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("s.docx");
    doc.save_as(&out).unwrap();
    let again = Document::open(&out).unwrap();
    let s = again.sections();
    assert_eq!(s.len(), 2);
    assert_eq!(s[0].props.page.orientation(), Orientation::Landscape);
    assert_eq!(s[1].props.page.orientation(), Orientation::Portrait);
}
